<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ref_x </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x         </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// ref_x points into the state machine</span></span>
